import Notification from"core/notification";export const action=(buttonId,link)=>{const button=document.getElementById(`btn-${buttonId}`);const dialog=document.getElementById(`confirm-${buttonId}`);if(!button||!dialog){return}button.style.display="";button.addEventListener("click",event=>{event.preventDefault();const title=dialog.getAttribute("title")||"";const message=dialog.querySelector("p")?.textContent||"";Notification.confirm(title,message,"Yes","No",()=>{window.location.href=link})})};